window.hideOrder = async (orderId) => {
  try {
    // Optimistic UI update
    const orderIndex = orders.findIndex(o => o.id === orderId);
    if (orderIndex > -1) {
      orders[orderIndex].kdsHidden = true;
      renderOrders();
    }

    // Persist to Firestore
    await updateDoc(doc(db, 'orders', orderId), { kdsHidden: true });
  } catch (error) {
    console.error("Failed to hide order:", error);
    alert("Failed to hide order. Are you connected to the internet?");
  }
};

window.changeOrderStatus = async (orderId, newStatus) => {
  const orderIndex = orders.findIndex(o => o.id === orderId);
  const prevStatus = orderIndex > -1 ? orders[orderIndex].status : null;

  try {
    // Optimistic UI update
    if (orderIndex > -1) {
      orders[orderIndex].status = newStatus;
      if (newStatus === 'completed' || newStatus === 'ready') {
        orders[orderIndex].updatedAt = new Date();
      }
      renderOrders();
    }

    // Call the backend to update Square + Firestore
    await updateSquareOrderStatus({ orderId, status: newStatus });
  } catch (error) {
    console.error("Failed to update order status:", error);
    // Revert optimistic update
    if (orderIndex > -1 && prevStatus) {
      orders[orderIndex].status = prevStatus;
      renderOrders();
    }
    alert("Failed to update order status. Please try again.");
  }
};

/**
 * Pure function to evaluate active deals against a cart.
 * Runs on both front-end (main.js) and back-end Cloud Functions.
 * 
 * @param {Array} cart - [{ id: string, name: string, price: number, qty: number }]
 * @param {Array} activeDeals - Array of Firestore deal documents
 * @param {Array} menuItems - Array of menu items [{ id, name, price, category }]
 * @returns {Object} { discountCents: number, appliedDeals: Array, itemDiscounts: Object, units: Array }
 */
export function evaluateDeals(cart, activeDeals, menuItems, appliedPromoCodes = []) {
  // 1. Flatten the cart into individual units for precise per-unit tracking
  const units = [];
  cart.forEach(item => {
    const menuInfo = menuItems.find(m => m.id === item.id) || {};
    const category = (menuInfo.category || '').toLowerCase();
    const originalPriceCents = Math.round((item.price || menuInfo.price || 0) * 100);
    
    for (let i = 0; i < item.qty; i++) {
      units.push({
        itemId: item.id,
        name: item.name || menuInfo.name || 'Unknown Item',
        category: category,
        originalPriceCents: originalPriceCents,
        priceCents: originalPriceCents,
        discountCents: 0,
        consumedBy: null // dealId
      });
    }
  });

  // 2. Filter active and scheduled deals
  const now = new Date();
  const validDeals = activeDeals.filter(deal => {
    if (!deal.active) return false;
    
    // Date checks
    if (deal.startDate) {
      const start = deal.startDate.toDate ? deal.startDate.toDate() : new Date(deal.startDate);
      if (now < start) return false;
    }
    if (deal.endDate) {
      const end = deal.endDate.toDate ? deal.endDate.toDate() : new Date(deal.endDate);
      if (now > end) return false;
    }
    return true;
  });

  // 3. Sort by priority descending
  validDeals.sort((a, b) => (b.priority || 0) - (a.priority || 0));

  const appliedDeals = [];
  const dealUsageCount = {};

  // 4. Evaluate each deal
  for (const deal of validDeals) {
    if (deal.usageLimitPerOrder !== null) {
      dealUsageCount[deal.id] = 0;
    }

    let matchesFound = true;
    while (matchesFound) {
      if (deal.usageLimitPerOrder !== null && dealUsageCount[deal.id] >= deal.usageLimitPerOrder) {
        break;
      }

      // Check conditions
      const condResult = matchConditions(units, deal.conditions, deal.type);
      if (!condResult.qualified) {
        matchesFound = false;
        break;
      }

      // Apply reward
      const rewardResult = applyReward(units, condResult.matchedUnitIndexes, deal);
      if (rewardResult.applied) {
        // Mark consumed units
        const allTouched = [...condResult.matchedUnitIndexes, ...rewardResult.rewardUnitIndexes];
        allTouched.forEach(idx => {
          if (!deal.stackable) {
            units[idx].consumedBy = deal.id;
          }
        });

        if (deal.usageLimitPerOrder !== null) {
          dealUsageCount[deal.id]++;
        }

        const existing = appliedDeals.find(ad => ad.dealId === deal.id);
        if (existing) {
          existing.discountCents += rewardResult.discountCents;
          existing.timesApplied += 1;
        } else {
          appliedDeals.push({
            dealId: deal.id,
            title: deal.title,
            discountCents: rewardResult.discountCents,
            type: deal.type,
            timesApplied: 1
          });
        }
      } else {
        matchesFound = false;
        break;
      }
    }
  }

  // Calculate totals
  const totalDiscountCents = units.reduce((sum, u) => sum + u.discountCents, 0);

  // Group item discounts by itemId for UI rendering
  const itemDiscounts = {};
  units.forEach(u => {
    if (u.discountCents > 0) {
      itemDiscounts[u.itemId] = (itemDiscounts[u.itemId] || 0) + u.discountCents;
    }
  });

  return {
    discountCents: totalDiscountCents,
    appliedDeals,
    itemDiscounts,
    units
  };
}

/**
 * Helper to match deal conditions against available units.
 */
function matchConditions(units, conditions, dealType) {
  if (!conditions) return { qualified: false };

  // 1. Order-wide deals
  if (conditions.appliesToWholeOrder) {
    const eligibleUnits = units.filter(u => u.consumedBy === null);
    const eligibleSubtotal = eligibleUnits.reduce((sum, u) => sum + u.priceCents, 0);
    const minSpendCents = Math.round((conditions.minQty || 0) * 100);
    
    if (eligibleSubtotal >= minSpendCents && eligibleUnits.length > 0) {
      return {
        qualified: true,
        matchedUnitIndexes: eligibleUnits.map(eu => units.indexOf(eu))
      };
    }
    return { qualified: false };
  }

  // 2. Combo / Bundle Deals (exact sets of items/categories required)
  if (dealType === 'bundle_price' || dealType === 'combo') {
    const tempMatchedIndexes = [];
    let matchedAll = true;

    // Match exact item ids
    if (conditions.itemIds && conditions.itemIds.length > 0) {
      for (const reqItemId of conditions.itemIds) {
        const foundIdx = units.findIndex((u, idx) => 
          u.itemId === reqItemId && 
          u.consumedBy === null && 
          !tempMatchedIndexes.includes(idx)
        );
        if (foundIdx !== -1) {
          tempMatchedIndexes.push(foundIdx);
        } else {
          matchedAll = false;
          break;
        }
      }
    }

    // Match exact category ids
    if (matchedAll && conditions.categoryIds && conditions.categoryIds.length > 0) {
      for (const reqCat of conditions.categoryIds) {
        const foundIdx = units.findIndex((u, idx) => 
          u.category === reqCat.toLowerCase() && 
          u.consumedBy === null && 
          !tempMatchedIndexes.includes(idx)
        );
        if (foundIdx !== -1) {
          tempMatchedIndexes.push(foundIdx);
        } else {
          matchedAll = false;
          break;
        }
      }
    }

    if (matchedAll) {
      return { qualified: true, matchedUnitIndexes: tempMatchedIndexes };
    }
    return { qualified: false };
  }

  // 3. Category / Item Specific Deals (requires at least minQty of matching items)
  const matchingUnits = [];
  units.forEach((u, idx) => {
    if (u.consumedBy !== null) return;
    
    const matchesItem = conditions.itemIds?.includes(u.itemId);
    const matchesCat = conditions.categoryIds?.includes(u.category);
    
    const hasItems = conditions.itemIds?.length > 0;
    const hasCats = conditions.categoryIds?.length > 0;

    if ((hasItems && matchesItem) || (hasCats && matchesCat)) {
      matchingUnits.push({ index: idx, price: u.priceCents });
    }
  });

  const requiredQty = conditions.minQty || 1;
  if (matchingUnits.length >= requiredQty) {
    // Take the matching units
    return {
      qualified: true,
      matchedUnitIndexes: matchingUnits.slice(0, requiredQty).map(mu => mu.index)
    };
  }

  return { qualified: false };
}

/**
 * Helper to apply reward and calculate discount amount.
 */
function applyReward(units, matchedUnitIndexes, deal) {
  const reward = deal.reward;
  if (!reward) return { applied: false };

  // 1. Bundle Package Price (Combo / Bundle)
  if (reward.discountType === 'fixedBundlePrice') {
    const currentSubtotal = matchedUnitIndexes.reduce((sum, idx) => sum + units[idx].priceCents, 0);
    const targetBundleCents = Math.round(reward.value * 100);
    const discountCents = currentSubtotal - targetBundleCents;

    if (discountCents > 0) {
      let appliedDiscount = 0;
      matchedUnitIndexes.forEach((idx, i) => {
        let unitDiscount = 0;
        if (i === matchedUnitIndexes.length - 1) {
          unitDiscount = discountCents - appliedDiscount;
        } else {
          unitDiscount = Math.round(discountCents * (units[idx].priceCents / currentSubtotal));
        }
        units[idx].priceCents -= unitDiscount;
        units[idx].discountCents += unitDiscount;
        appliedDiscount += unitDiscount;
      });
      return { applied: true, discountCents, rewardUnitIndexes: [] };
    }
    return { applied: false };
  }

  // 2. Percent Off
  if (reward.discountType === 'percent') {
    let totalDiscount = 0;
    matchedUnitIndexes.forEach(idx => {
      const unitDiscount = Math.round(units[idx].priceCents * (reward.value / 100));
      units[idx].priceCents -= unitDiscount;
      units[idx].discountCents += unitDiscount;
      totalDiscount += unitDiscount;
    });
    return { applied: true, discountCents: totalDiscount, rewardUnitIndexes: [] };
  }

  // 3. Fixed Amount Off
  if (reward.discountType === 'fixed') {
    if (deal.conditions?.appliesToWholeOrder) {
      // Order-level fixed off
      const currentSubtotal = matchedUnitIndexes.reduce((sum, idx) => sum + units[idx].priceCents, 0);
      const discountCents = Math.min(Math.round(reward.value * 100), currentSubtotal);
      
      if (discountCents > 0) {
        let appliedDiscount = 0;
        matchedUnitIndexes.forEach((idx, i) => {
          let unitDiscount = 0;
          if (i === matchedUnitIndexes.length - 1) {
            unitDiscount = discountCents - appliedDiscount;
          } else {
            unitDiscount = Math.round(discountCents * (units[idx].priceCents / currentSubtotal));
          }
          units[idx].priceCents -= unitDiscount;
          units[idx].discountCents += unitDiscount;
          appliedDiscount += unitDiscount;
        });
        return { applied: true, discountCents, rewardUnitIndexes: [] };
      }
      return { applied: false };
    } else {
      // Item-level fixed off (applies to each matching unit)
      let totalDiscount = 0;
      matchedUnitIndexes.forEach(idx => {
        const unitDiscount = Math.min(Math.round(reward.value * 100), units[idx].priceCents);
        units[idx].priceCents -= unitDiscount;
        units[idx].discountCents += unitDiscount;
        totalDiscount += unitDiscount;
      });
      return { applied: true, discountCents: totalDiscount, rewardUnitIndexes: [] };
    }
  }

  // 4. Free Item (BOGO / Free Gift)
  if (reward.discountType === 'freeItem') {
    // Find unconsumed reward items in cart
    const eligibleRewardUnitIndexes = [];
    units.forEach((u, idx) => {
      if (u.consumedBy !== null) return;
      if (matchedUnitIndexes.includes(idx)) return; // Can't be a trigger unit
      
      if (reward.rewardItemIds?.includes(u.itemId)) {
        eligibleRewardUnitIndexes.push(idx);
      }
    });

    if (eligibleRewardUnitIndexes.length > 0) {
      const rewardUnitIndexes = eligibleRewardUnitIndexes.slice(0, reward.rewardQty || 1);
      let totalDiscount = 0;
      rewardUnitIndexes.forEach(idx => {
        const unitDiscount = units[idx].priceCents;
        units[idx].priceCents = 0;
        units[idx].discountCents += unitDiscount;
        totalDiscount += unitDiscount;
      });
      return { applied: true, discountCents: totalDiscount, rewardUnitIndexes };
    }
    return { applied: false };
  }

  return { applied: false };
}

import './style.css';
import { db } from './firebase.js';
import { collection, addDoc, getDocs, serverTimestamp, onSnapshot, query, where } from 'firebase/firestore';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { app } from './firebase.js';
import { evaluateDeals } from './lib/deals-evaluator.js';
import { getLang, t } from './i18n/index.js';
import './analytics.js';

// ─────────────────────────────────────────────────────────────────
// SQUARE CONFIGURATION
// Replace with your Sandbox Application ID from developer.squareup.com
// In production, swap for your Production Application ID
// ─────────────────────────────────────────────────────────────────
const SQUARE_APP_ID = import.meta.env.VITE_SQUARE_APP_ID;
const SQUARE_LOCATION_ID = import.meta.env.VITE_SQUARE_LOCATION_ID;
const TAX_RATE = 0.1025; // LA County / Reseda sales tax rate (10.25%)

// Firebase Functions
const functions = getFunctions(app);
const processSquarePayment = httpsCallable(functions, 'processSquarePayment');

// Menu data loaded from Firestore
let menuItems = [];
// State
let cart = [];
let activeDeals = [];
let appliedPromoCodes = []; // list of manually applied codes

let squareCard = null; // Square card payment method instance

// Pickup State
let pickupConfig = {
  basePrepTimeMinutes: 15,
  perOrderIncrementMinutes: 3,
  maxWaitMinutes: 60,
  minLeadTimeMinutes: 20,
  maxScheduleDaysAhead: 3,
  slotIntervalMinutes: 15,
  prepBufferBeforeCloseMinutes: 30,
  businessHours: { open: "12:00", close: "22:30" }
};
let activeAsapOrderCount = 0;

// Load Pickup Config
import { doc } from 'firebase/firestore';
onSnapshot(doc(db, 'settings', 'pickupConfig'), (docSnap) => {
  if (docSnap.exists()) {
    pickupConfig = { ...pickupConfig, ...docSnap.data() };
    updateAsapEstimate();
    if (typeof checkBusinessHours === 'function') checkBusinessHours();
    updateFooterHours();
  }
});

onSnapshot(doc(db, 'liveStats', 'current'), (docSnap) => {
  if (docSnap.exists()) {
    activeAsapOrderCount = docSnap.data().activeAsapOrderCount || 0;
    updateAsapEstimate();
  }
});

function updateFooterHours() {
  if (!pickupConfig.businessHours) return;
  const daysMap = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const openDaysStr = pickupConfig.openDays && pickupConfig.openDays.length === 7 
    ? 'Every Day' 
    : (pickupConfig.openDays || [0,1,2,3,4,5,6]).map(d => daysMap[d].substring(0,3)).join(', ');
    
  function formatTime(time24) {
    const [h, m] = time24.split(':').map(Number);
    const ampm = h >= 12 ? 'PM' : 'AM';
    let displayH = h % 12;
    displayH = displayH ? displayH : 12;
    return `${displayH}${m > 0 ? ':' + String(m).padStart(2, '0') : ''}${ampm}`;
  }
  
  const openTime = formatTime(pickupConfig.businessHours.open);
  const closeTime = formatTime(pickupConfig.businessHours.close);
  const text = `${openDaysStr} ${openTime}–${closeTime}`;
  
  document.querySelectorAll('.footer-hours-display').forEach(el => {
    el.textContent = text;
  });
}

// ──────────────────────────────────────────
// BUSINESS HOURS ENFORCEMENT
// ──────────────────────────────────────────
window.isStoreClosed = false;

function checkBusinessHours() {
  const now = new Date();
  if (!pickupConfig.businessHours) return;
  const [openH, openM] = pickupConfig.businessHours.open.split(':').map(Number);
  const [closeH, closeM] = pickupConfig.businessHours.close.split(':').map(Number);
  
  const currentH = now.getHours();
  const currentM = now.getMinutes();
  
  const currentTime = currentH * 60 + currentM;
  const openTime = openH * 60 + openM;
  const closeTime = closeH * 60 + closeM;
  
  let isClosed = false;
  
  // 1. Check if today is a valid open day
  const currentDay = now.getDay(); // 0 is Sunday, 1 is Monday...
  if (pickupConfig.openDays && Array.isArray(pickupConfig.openDays)) {
    if (!pickupConfig.openDays.includes(currentDay)) {
      isClosed = true;
    }
  }
  
  // 2. Check time
  if (!isClosed) {
    if (closeTime > openTime) {
      if (currentTime < openTime || currentTime >= closeTime) isClosed = true;
    } else {
      // Crosses midnight e.g. open 11:00, close 02:00
      if (currentTime < openTime && currentTime >= closeTime) isClosed = true;
    }
  }
  
  window.isStoreClosed = isClosed;

  // Toggle banner
  let banner = document.getElementById('store-closed-banner');
  if (isClosed) {
    if (!banner) {
      banner = document.createElement('div');
      banner.id = 'store-closed-banner';
      banner.className = 'store-closed-banner';
      
      const pType = document.querySelector('input[name="pickup_type"]:checked')?.value || 'asap';
      let message = `We are currently closed. Next open at ${pickupConfig.businessHours.open}`;
      
      if (pType === 'asap') {
         message += " — ASAP ordering is disabled. Please select a Scheduled pickup time.";
      }
      
      banner.innerHTML = `<span><svg style="width:20px;height:20px;fill:currentColor;vertical-align:middle;margin-right:8px" viewBox="0 0 24 24"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm-.22-13h-.06c-.4 0-.72.32-.72.72v4.72c0 .35.18.68.49.86l4.15 2.49c.34.2.78.1.98-.24a.71.71 0 00-.25-.99l-3.87-2.3V7.72c0-.4-.32-.72-.72-.72z"/></svg>${message}</span>`;
      document.body.prepend(banner);
    } else {
      const pType = document.querySelector('input[name="pickup_type"]:checked')?.value || 'asap';
      let message = `We are currently closed. Next open at ${pickupConfig.businessHours.open}`;
      if (pType === 'asap') {
         message += " — ASAP ordering is disabled. Please select a Scheduled pickup time.";
      }
      banner.innerHTML = `<span><svg style="width:20px;height:20px;fill:currentColor;vertical-align:middle;margin-right:8px" viewBox="0 0 24 24"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm-.22-13h-.06c-.4 0-.72.32-.72.72v4.72c0 .35.18.68.49.86l4.15 2.49c.34.2.78.1.98-.24a.71.71 0 00-.25-.99l-3.87-2.3V7.72c0-.4-.32-.72-.72-.72z"/></svg>${message}</span>`;
    }
  } else {
    if (banner) banner.remove();
  }
}

function updateAsapEstimate() {
  const el = document.getElementById('asap-estimate');
  if (el) {
    const rawWait = pickupConfig.basePrepTimeMinutes + (activeAsapOrderCount * pickupConfig.perOrderIncrementMinutes);
    const wait = Math.min(rawWait, pickupConfig.maxWaitMinutes);
    el.textContent = `(~${wait} min)`;
  }
}

window.togglePickupType = () => {
  const pType = document.querySelector('input[name="pickup_type"]:checked').value;
  if (pType === 'scheduled') {
    document.getElementById('scheduled-pickup-options').style.display = 'block';
    populateDates();
  } else {
    document.getElementById('scheduled-pickup-options').style.display = 'none';
  }
  if (typeof checkBusinessHours === 'function') checkBusinessHours();
  if (typeof updateCartUI === 'function') updateCartUI();
};

function populateDates() {
  const dateSelect = document.getElementById('pickup-date-select');
  if (!dateSelect) return;
  dateSelect.innerHTML = '';
  
  const now = new Date();
  
  for (let i = 0; i <= pickupConfig.maxScheduleDaysAhead; i++) {
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i);
    const dayOfWeek = d.getDay();
    if (pickupConfig.openDays && Array.isArray(pickupConfig.openDays) && !pickupConfig.openDays.includes(dayOfWeek)) {
      continue;
    }
    const opt = document.createElement('option');
    opt.value = d.toISOString().split('T')[0];
    opt.textContent = i === 0 ? 'Today' : i === 1 ? 'Tomorrow' : d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
    dateSelect.appendChild(opt);
  }
  
  updateTimeSlots();
}

window.updateTimeSlots = updateTimeSlots;
function updateTimeSlots() {
  const dateStr = document.getElementById('pickup-date-select').value;
  const timeSelect = document.getElementById('pickup-time-select');
  if (!dateStr || !timeSelect) return;
  timeSelect.innerHTML = '';
  
  const now = new Date();
  const selectedDate = new Date(dateStr + "T00:00:00");
  const isToday = selectedDate.getDate() === now.getDate() && selectedDate.getMonth() === now.getMonth() && selectedDate.getFullYear() === now.getFullYear();
  
  const [openH, openM] = pickupConfig.businessHours.open.split(':').map(Number);
  const [closeH, closeM] = pickupConfig.businessHours.close.split(':').map(Number);
  
  let startH = openH;
  let startM = openM;
  
  if (isToday) {
    // If today, start from now + lead time
    const leadMs = pickupConfig.minLeadTimeMinutes * 60000;
    const earliestTime = new Date(now.getTime() + leadMs);
    
    if (earliestTime.getHours() > startH || (earliestTime.getHours() === startH && earliestTime.getMinutes() > startM)) {
       startH = earliestTime.getHours();
       startM = Math.ceil(earliestTime.getMinutes() / pickupConfig.slotIntervalMinutes) * pickupConfig.slotIntervalMinutes;
       if (startM >= 60) {
         startH++;
         startM = 0;
       }
    }
  }
  
  // End time is close - buffer
  let endH = closeH;
  let endM = closeM - pickupConfig.prepBufferBeforeCloseMinutes;
  if (endM < 0) {
    endH--;
    endM += 60;
  }
  
  let currentH = startH;
  let currentM = startM;
  let hasSlots = false;
  
  while (currentH < endH || (currentH === endH && currentM <= endM)) {
    hasSlots = true;
    const ampm = currentH >= 12 ? 'PM' : 'AM';
    const displayH = currentH % 12 === 0 ? 12 : currentH % 12;
    const displayM = currentM.toString().padStart(2, '0');
    
    const opt = document.createElement('option');
    opt.value = `${currentH.toString().padStart(2, '0')}:${displayM}:00`;
    opt.textContent = `${displayH}:${displayM} ${ampm}`;
    timeSelect.appendChild(opt);
    
    currentM += pickupConfig.slotIntervalMinutes;
    if (currentM >= 60) {
      currentH++;
      currentM -= 60;
    }
  }
  
  if (!hasSlots) {
    document.getElementById('pickup-time-warning').style.display = 'block';
    timeSelect.disabled = true;
  } else {
    document.getElementById('pickup-time-warning').style.display = 'none';
    timeSelect.disabled = false;
  }
}

