});

// Shared mobile nav logic for all pages
import { db } from './firebase.js';
import { doc, getDoc } from 'firebase/firestore';
import { getLang, setLang, toggleLang, applyTranslations } from './i18n/index.js';

export function initNav(activePage = '') {
  const hamburger = document.getElementById('nav-hamburger');
  const drawer = document.getElementById('nav-mobile-drawer');
  if (!hamburger || !drawer) return;

  hamburger.addEventListener('click', () => {
    hamburger.classList.toggle('open');
    drawer.classList.toggle('open');
  });

  // Language setup
  setLang(getLang());
  applyTranslations();

  const langToggles = document.querySelectorAll('.site-lang-toggle');
  langToggles.forEach(btn => {
    btn.addEventListener('click', () => {
      toggleLang();
      applyTranslations();
      // If we are on menu.html, we need to re-render the menu
      if (typeof window.renderMenu === 'function') {
        window.renderMenu();
      }
    });
  });

  // Close drawer when a link is clicked
  drawer.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => {
      hamburger.classList.remove('open');
      drawer.classList.remove('open');
    });
  });

  // Close on outside click
  document.addEventListener('click', (e) => {
    if (!hamburger.contains(e.target) && !drawer.contains(e.target)) {
      hamburger.classList.remove('open');
      drawer.classList.remove('open');
    }
  });

  checkGlobalPopup();
}

async function checkGlobalPopup() {
  try {
    const snap = await getDoc(doc(db, 'settings', 'popup'));
    if (!snap.exists()) return;

    const data = snap.data();
    if (!data.active) return;

    // Check if user already dismissed this version
    const lastUpdate = data.updatedAt?.toMillis() || 0;
    const dismissedKey = 'bigi_popup_dismissed';
    const lastDismissed = localStorage.getItem(dismissedKey);

    if (lastDismissed && parseInt(lastDismissed) >= lastUpdate) {
      return; // Already dismissed this specific popup version
    }

    renderPopup(data, lastUpdate, dismissedKey);
  } catch(e) {
    console.error('Error fetching popup:', e);
  }
}

function renderPopup(data, lastUpdate, dismissedKey) {
  const overlay = document.createElement('div');
  overlay.className = 'global-popup-overlay';

  let btnHtml = '';
  if (data.buttonText && data.buttonUrl) {
    btnHtml = `<a href="${data.buttonUrl}" class="btn-primary" style="margin-top: 20px; display: inline-block; text-decoration: none;">${data.buttonText}</a>`;
  }

  // Format message to handle line breaks natively
  const formattedMessage = (data.message || '').replace(/\n/g, '<br>');

  overlay.innerHTML = `
    <div class="global-popup-content">
      <button class="global-popup-close">&times;</button>
      <h2 style="font-family: 'Barlow Condensed'; font-size: 28px; font-weight: 700; text-transform: uppercase; margin-bottom: 12px; letter-spacing: 1px; color: var(--white);">${data.title || 'Announcement'}</h2>
      <p style="color: var(--gray); line-height: 1.5; font-size: 16px; margin: 0;">${formattedMessage}</p>
      ${btnHtml}
    </div>
  `;

  document.body.appendChild(overlay);

  // Trigger animation
  requestAnimationFrame(() => {
    overlay.classList.add('show');
  });

  // Close logic
  const closeBtn = overlay.querySelector('.global-popup-close');
  const closePopup = () => {
    overlay.classList.remove('show');
    localStorage.setItem(dismissedKey, lastUpdate.toString());
    setTimeout(() => overlay.remove(), 400); // Wait for transition
  };

  closeBtn.addEventListener('click', closePopup);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closePopup();
  });
}

import { app, db } from './firebase.js';
import { doc, onSnapshot, updateDoc } from 'firebase/firestore';
import { getMessaging, getToken } from 'firebase/messaging';

document.addEventListener('DOMContentLoaded', () => {
  const urlParams = new URLSearchParams(window.location.search);
  const orderId = urlParams.get('orderId');
  const token = urlParams.get('token');

  const loadingState = document.getElementById('loading-state');
  const errorState = document.getElementById('error-state');
  const mainContent = document.getElementById('main-content');
  const errorMsg = document.getElementById('error-msg');

  if (!orderId || !token) {
    showError("Invalid tracking link. Missing order ID or token.");
    return;
  }

  const orderRef = doc(db, 'orders', orderId);
  let previousStatus = null;

  onSnapshot(orderRef, (docSnap) => {
    if (!docSnap.exists()) {
      showError("We couldn't find an order with this link.");
      return;
    }

    const order = docSnap.data();
    console.log("Firestore order status:", order.status);

    // Trigger local HTML5 notification if status changes to ready
    if (previousStatus && previousStatus !== 'ready' && order.status === 'ready') {
      if (Notification.permission === 'granted') {
        new Notification('Order Ready for Pickup!', {
          body: 'Your Bigi Awasaana order is ready. Come and get it!',
          icon: '/android-chrome-192x192.png'
        });
      }
    }
    previousStatus = order.status;

    // Security check: verify token
    if (order.accessToken !== token) {
      showError("Unauthorized. Invalid access token.");
      return;
    }

    renderOrder(orderId, order);
    
    // Request push notification permissions
    if (order.status !== 'completed') {
      setupPushNotifications(orderId, order.fcmToken);
    }
    
  }, (err) => {
    console.error("Firebase read error:", err);
    showError("Failed to connect to real-time updates. Please refresh the page.");
  });

  async function setupPushNotifications(orderId, existingToken) {
    try {
      const messaging = getMessaging(app);
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        // You would normally pass a VAPID key to getToken: getToken(messaging, { vapidKey: '...' })
        // If omitted, Firebase uses the default project sender ID.
        const currentToken = await getToken(messaging);
        if (currentToken && currentToken !== existingToken) {
          const orderRef = doc(db, 'orders', orderId);
  let previousStatus = null;
          await updateDoc(orderRef, { fcmToken: currentToken });
          console.log('FCM token saved for order notifications');
        }
      }
    } catch (err) {
      console.log('Push notifications not enabled or failed:', err);
      // Silent fail
    }
  }

  function showError(msg) {
    loadingState.style.display = 'none';
    mainContent.style.display = 'none';
    errorState.style.display = 'block';
    errorMsg.textContent = msg;
  }

  function renderOrder(id, order) {
    loadingState.style.display = 'none';
    mainContent.style.display = 'flex';

    // Populate data
    document.getElementById('order-customer').textContent = order.customerName || 'Guest';
    document.getElementById('order-id').textContent = '#' + id.slice(-4).toUpperCase();
    document.getElementById('order-total').textContent = `$${(order.total || 0).toFixed(2)}`;

    const itemsContainer = document.getElementById('order-items');
    itemsContainer.innerHTML = '';
    (order.items || []).forEach(item => {
      const li = document.createElement('li');
      li.className = 'item-row';
      li.innerHTML = `
        <div>
          <span class="item-qty">${item.quantity}×</span>
          <span style="color: var(--white);">${item.name}</span>
        </div>
      `;
      itemsContainer.appendChild(li);
    });

    // Update UI based on status
    const statusMap = {
      'pending': { step: 1, title: 'Preparing', desc: "We've received your order and are getting it ready.", fill: '0%' },
      'preparing': { step: 1, title: 'Preparing', desc: "Your food is being freshly prepared in the kitchen.", fill: '15%' },
      'ready': { step: 2, title: 'Ready for Pickup', desc: "Your order is hot and ready at the counter!", fill: '50%', theme: 'ready' },
      'completed': { step: 3, title: 'Thank You!', desc: "We hope you enjoy your meal. Come again soon!", fill: '100%', theme: 'ready' }
    };

    const state = statusMap[order.status] || statusMap['pending'];

    document.getElementById('status-title').textContent = state.title;
    document.getElementById('status-desc').textContent = state.desc;
    document.getElementById('progress-fill').style.width = state.fill;

    // Theme update
    if (state.theme === 'ready') {
      document.body.classList.add('theme-ready');
    } else {
      document.body.classList.remove('theme-ready');
    }

    // Step classes
    [1, 2, 3].forEach(stepNum => {
      const stepEl = document.getElementById(`step-${stepNum}`);
      stepEl.classList.remove('active', 'completed-step');
      
      if (stepNum < state.step) {
        stepEl.classList.add('completed-step');
      } else if (stepNum === state.step) {
        stepEl.classList.add('active');
      }
    });

    // Wait time logic
    const waitContainer = document.getElementById('wait-time-container');
    const waitText = document.getElementById('wait-time-text');
    
    if (order.status === 'pending' || order.status === 'preparing') {
      if (order.estimatedReadyAt) {
        // Handle Firestore timestamp or standard date
        const readyTime = order.estimatedReadyAt.toDate ? order.estimatedReadyAt.toDate() : new Date(order.estimatedReadyAt);
        const now = new Date();
        const diffMins = Math.ceil((readyTime - now) / 60000);
        
        if (diffMins > 0) {
          waitText.textContent = `Ready in ~${diffMins} minutes`;
          waitContainer.style.display = 'block';
        } else {
          waitText.textContent = `Ready very soon`;
          waitContainer.style.display = 'block';
        }
      } else {
        waitContainer.style.display = 'none';
      }
    } else {
      waitContainer.style.display = 'none';
    }
  }
});

import { db } from './firebase.js';
import { collection, doc, onSnapshot } from 'firebase/firestore';

let menuItems = [];
let categories = [];
let featuredItems = [];
let currentFeaturedIndex = 0;
let featuredRotationInterval = null;

// Handle Redirects for static menu screens
const urlParams = new URLSearchParams(window.location.search);
const screenParam = urlParams.get('screen');
if (screenParam === '1') {
  window.location.replace('/tv1');
} else if (screenParam === '2') {
  window.location.replace('/tv2');
}

// ─────────────────────────────────────────────────────────────────
// AUTO-FULLSCREEN, MANUAL TOGGLE, & WAKE LOCK
// ─────────────────────────────────────────────────────────────────
let wakeLock = null;

async function requestWakeLock() {
  try {
    if ('wakeLock' in navigator) {
      wakeLock = await navigator.wakeLock.request('screen');
      wakeLock.addEventListener('release', () => {
        console.log('Screen Wake Lock released');
      });
      console.log('Screen Wake Lock acquired');
    }
  } catch (err) {
    console.error('Wake Lock error:', err.name, err.message);
  }
}

// Re-request wake lock if visibility changes
document.addEventListener('visibilitychange', async () => {
  if (wakeLock !== null && document.visibilityState === 'visible') {
    requestWakeLock();
  }
});

document.getElementById('tv-start-overlay')?.addEventListener('click', (e) => {
  e.currentTarget.style.display = 'none';

  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen().catch(() => {});
  }
  
  requestWakeLock();
  
  const video = document.getElementById('tv-nosleep');
